package org.apache.commons.lang.enums;

import static org.junit.Assert.*;

import java.lang.reflect.Method;
import java.util.Iterator;
import java.util.List;

import org.junit.Before;
import org.junit.Test;

/**
 * Concrete subclass of {@link ValuedEnum} used only for testing.
 */
public class ValuedEnumTest {

    /** Simple enum with three values. */
    public static final class TestEnum extends ValuedEnum {
        private static final long serialVersionUID = 1L;

        public static final TestEnum ONE   = new TestEnum("ONE",   1);
        public static final TestEnum TWO   = new TestEnum("TWO",   2);
        public static final TestEnum THREE = new TestEnum("THREE", 3);

        private TestEnum(String name, int value) {
            super(name, value);
        }

        /** Helper to expose the protected static getEnum(Class,int) method. */
        public static TestEnum getEnum(int value) {
            return (TestEnum) ValuedEnum.getEnum(TestEnum.class, value);
        }
    }

    /** Another enum type to test ClassCastException in compareTo. */
    public static final class OtherEnum extends ValuedEnum {
        private static final long serialVersionUID = 1L;
        public static final OtherEnum A = new OtherEnum("A", 10);
        private OtherEnum(String name, int value) {
            super(name, value);
        }
    }

    private TestEnum one;
    private TestEnum two;
    private TestEnum three;

    @Before
    public void setUp() {
        // Assign the static instances to instance fields for readability.
        one   = TestEnum.ONE;
        two   = TestEnum.TWO;
        three = TestEnum.THREE;
    }

    // -------------------------------------------------------------------------
    //  Tests for getValue()
    // -------------------------------------------------------------------------
    @Test
    public void testGetValue() {
        assertEquals(1, one.getValue());
        assertEquals(2, two.getValue());
        assertEquals(3, three.getValue());
    }

    // -------------------------------------------------------------------------
    //  Tests for compareTo(Object)
    // -------------------------------------------------------------------------
    @Test
    public void testCompareToLessThan() {
        // ONE < TWO
        assertTrue(one.compareTo(two) < 0);
        // TWO < THREE
        assertTrue(two.compareTo(three) < 0);
    }

    @Test
    public void testCompareToGreaterThan() {
        // THREE > TWO
        assertTrue(three.compareTo(two) > 0);
        // TWO > ONE
        assertTrue(two.compareTo(one) > 0);
    }

    @Test
    public void testCompareToEqual() {
        // same instance
        assertEquals(0, one.compareTo(one));
        // different instance with same value (none exist, but compare with itself)
        assertEquals(0, two.compareTo(TestEnum.TWO));
    }

    @Test(expected = NullPointerException.class)
    public void testCompareToNull() {
        one.compareTo(null);
    }

    @Test(expected = ClassCastException.class)
    public void testCompareToDifferentEnumType() {
        // compare TestEnum with OtherEnum – should throw ClassCastException
        one.compareTo(OtherEnum.A);
    }

    // -------------------------------------------------------------------------
    //  Tests for protected static getEnum(Class,int)
    // -------------------------------------------------------------------------
    @Test
    public void testGetEnumValidValue() {
        assertSame(one,   TestEnum.getEnum(1));
        assertSame(two,   TestEnum.getEnum(2));
        assertSame(three, TestEnum.getEnum(3));
    }

    @Test
    public void testGetEnumInvalidValueReturnsNull() {
        assertNull(TestEnum.getEnum(99));   // no enum with value 99
    }

    @Test(expected = IllegalArgumentException.class)
    public void testGetEnumNullClassThrowsException() throws Exception {
        // Use reflection to call the protected method directly with a null class.
        Method m = ValuedEnum.class.getDeclaredMethod("getEnum", Class.class, int.class);
        m.setAccessible(true);
        m.invoke(null, null, 1);   // first argument (the instance) is ignored for static method
    }

    // -------------------------------------------------------------------------
    //  Tests for toString()
    // -------------------------------------------------------------------------
    @Test
    public void testToStringFormat() {
        String expectedOne = "TestEnum[ONE=1]";
        String expectedTwo = "TestEnum[TWO=2]";
        String expectedThree = "TestEnum[THREE=3]";

        assertEquals(expectedOne,   one.toString());
        assertEquals(expectedTwo,   two.toString());
        assertEquals(expectedThree, three.toString());
    }

    @Test
    public void testToStringCaching() {
        // First call builds the string, second call should return the same cached instance.
        String first = one.toString();
        String second = one.toString();
        assertSame("toString should be cached and return same String instance", first, second);
    }

    // -------------------------------------------------------------------------
    //  Additional sanity checks that rely on Enum superclass behaviour
    // -------------------------------------------------------------------------
    @Test
    public void testEnumListContainsAllValues() {
        // Enum.getEnumList is defined in the superclass (org.apache.commons.lang.enums.Enum)
        // Verify that the list returned for TestEnum contains exactly the three items.
        List list = Enum.getEnumList(TestEnum.class);
        assertEquals(3, list.size());
        assertTrue(list.contains(one));
        assertTrue(list.contains(two));
        assertTrue(list.contains(three));
    }

    @Test
    public void testIterator() {
        // Verify that the iterator traverses the same elements in the same order.
        Iterator it = Enum.iterator(TestEnum.class);
        assertTrue(it.hasNext());
        assertEquals(one,   it.next());
        assertTrue(it.hasNext());
        assertEquals(two,   it.next());
        assertTrue(it.hasNext());
        assertEquals(three, it.next());
        assertFalse(it.hasNext());
    }
}
